/** Polls `predicate` every 10 ms for up to 10 s (a fresh `bun` CLI child takes a moment to boot). */
async function waitFor(predicate: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 1000; attempt += 1) {
    if (predicate()) return;
    await Bun.sleep(10);
  }
  throw new Error("condition never became true");
}

function spawnShim(args: string[]): { proc: Bun.Subprocess<"ignore", "pipe", "pipe">; stdout(): Promise<string>; stderr(): Promise<string> } {
  const proc = Bun.spawn([process.execPath, CLI_ENTRYPOINT, "worker-shim", ...args, "--", "bun", FAKE_OMP], {
    stdin: "ignore", stdout: "pipe", stderr: "pipe",
  });
  cleanups.push(() => { proc.kill(); });
  return { proc, stdout: () => new Response(proc.stdout).text(), stderr: () => new Response(proc.stderr).text() };
}

